    [InlineData("a.nowak@example.com", "   \n ")]
    [InlineData("", "Boiler broken")]
    [InlineData("  ", "Boiler broken")]
    public async Task Blank_sender_or_text_is_400_problem_details_and_stores_nothing(string sender, string text)
    {
